fragment ActorFields on Actor { __typename login }

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment CheckRunFields on CheckRun {
  id
  name
  status
  conclusion
  startedAt
  completedAt
  detailsUrl
  url
  summary
  title
  isRequired(pullRequestNumber: $number)
}

fragment CheckRunsPage on CheckRunConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckRunFields }
}

fragment CheckSuiteFields on CheckSuite {
  id
  status
  conclusion
  createdAt
  updatedAt
  url
  app { slug name }
  push {
    id
    previousSha
    nextSha
    pusher { ...ActorFields }
  }
  workflowRun {
    id
    url
    workflow { name }
  }
  checkRuns(first: 50) { ...CheckRunsPage }
}

fragment CheckSuitesPage on CheckSuiteConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckSuiteFields }
}

fragment CommitFields on Commit {
  id
  oid
  abbreviatedOid
  messageHeadline
  committedDate
  authoredDate
  author {
    name
    user { ...ActorFields }
  }
  checkSuites(first: 10) { ...CheckSuitesPage }
